# frozen_string_literal: true

# Keeps the SDK's copy of the Flashpi API contract and the RBS types generated from it in sync.
#
#   ruby scripts/openapi.rb sync      download the public OpenAPI document, then generate
#   ruby scripts/openapi.rb generate  regenerate sig/flashpi/types.rbs
#   ruby scripts/openapi.rb check     fail when the generated file is out of date (CI)
#
# The source is the public document the docs publish (https://flashpi.com.ec/docs/openapi.json),
# because the API repository is private. Override it with FLASHPI_OPENAPI_URL, or point
# FLASHPI_OPENAPI_FILE at a local file (for example a flashpi-api checkout).
#
# The generator uses the standard library only. It turns every component schema into an RBS type
# alias in Flashpi::Types (a record for an object, with the keys of the API in camelCase), and the
# query of every operation that takes one into a record too. It fails on any construct it does
# not know, so a change in the document can never be translated silently into a wrong type.

require "json"
require "net/http"
require "uri"

# The generator of sig/flashpi/types.rbs and the commands of this script.
module OpenAPI
  ROOT = File.expand_path("..", __dir__)
  CONTRACT_PATH = File.join(ROOT, "openapi", "openapi.json")
  TYPES_PATH = File.join(ROOT, "sig", "flashpi", "types.rbs")
  DEFAULT_URL = "https://flashpi.com.ec/docs/openapi.json"

  LINE_LENGTH = 100
  INDENT = "  "

  HEADER = <<~RBS
    # Types of the Flashpi API, generated from its public OpenAPI document.
    #
    # GENERATED by scripts/openapi.rb from openapi/openapi.json. Do not edit by hand: run
    # `ruby scripts/openapi.rb sync` (or `generate`).
  RBS

  # Keywords that only constrain values (lengths, patterns, ranges) or document them: an RBS type
  # cannot express them, so they are read for the comments or skipped.
  ANNOTATION_KEYWORDS = %w[
    description example examples format pattern minLength maxLength minimum maximum
    exclusiveMinimum exclusiveMaximum multipleOf minItems maxItems uniqueItems minProperties
    maxProperties default title deprecated
  ].freeze
  STRUCTURE_KEYWORDS = %w[
    type properties required items enum const $ref allOf anyOf oneOf discriminator
    additionalProperties not
  ].freeze
  SCALARS = {
    "string" => "String", "integer" => "Integer", "number" => "Integer | Float", "boolean" => "bool",
    "null" => "nil"
  }.freeze
  METHODS = %w[get post put patch delete].freeze
  # What a path item may hold besides its operations.
  PATH_ITEM_KEYS = %w[summary description parameters].freeze
  # What a parameter may hold: no `content`, `style`, `explode`, `allowReserved` or
  # `allowEmptyValue`, whose serialization the SDK does not follow.
  PARAMETER_KEYS = %w[name in required description schema deprecated example examples].freeze
  # A record key RBS writes without quotes, and a type alias name.
  KEY = /\A[A-Za-z_][A-Za-z0-9_]*\z/
  ALIAS = /\A[a-z_][a-z0-9_]*\z/
  # Ruby's and RBS's keywords cannot name a type alias.
  RESERVED = %w[
    alias attr_accessor attr_reader attr_writer bool bot class def end extend false include instance
    interface module nil out prepend private public self singleton super top true type unchecked
    untyped void
  ].freeze

  # The document holds something this generator cannot translate faithfully.
  class GenerationError < StandardError; end

  Field = Struct.new(:name, :type, :required, :doc)

  # A record (when `fields` is set) or another type (`expression`).
  Definition = Struct.new(:name, :doc, :fields, :expression)

  module_function

  # "CreateWebhookEndpoint" to "create_webhook_endpoint".
  def snake(name)
    name.gsub(/([A-Z]+)([A-Z][a-z])/, '\1_\2').gsub(/([a-z0-9])([A-Z])/, '\1_\2').downcase
  end

  def upper_first(value)
    value[0].to_s.upcase + value[1..].to_s
  end

  # Translates an OpenAPI 3.1 document into RBS.
  class Generator
    def initialize(document)
      @document = schema(document, "document")
      version = @document["openapi"]
      unless version.is_a?(String) && version.start_with?("3.1")
        raise GenerationError,
              "Only OpenAPI 3.1 documents are supported"
      end

      components = schema(@document.fetch("components", {}), "components")
      @schemas = schema(components.fetch("schemas", {}), "components.schemas")
      @parameters = schema(components.fetch("parameters", {}), "components.parameters")
      @definitions = {}
    end

    def generate
      @schemas.keys.sort.each { |name| define_component(name, schema(@schemas[name], name)) }
      define_queries
      body = @definitions.keys.sort.map { |name| emit(@definitions[name]) }.join("\n\n")
      "#{HEADER}module Flashpi\n#{INDENT}module Types\n#{body}\n#{INDENT}end\nend\n"
    end

    private

    def schema(value, where)
      raise GenerationError, "#{where}: expected a schema object" unless value.is_a?(Hash)

      value
    end

    def list(value, where)
      raise GenerationError, "#{where}: expected a list" unless value.is_a?(Array)

      value
    end

    def text(value, where)
      raise GenerationError, "#{where}: expected a string" unless value.is_a?(String)

      value
    end

    # The alias of a component schema or of an inline enum or object.
    def alias_name(hint)
      name = OpenAPI.snake(hint)
      unless ALIAS.match?(name) && !RESERVED.include?(name)
        raise GenerationError,
              "#{hint} is not a valid RBS type name"
      end

      name
    end

    def define(definition)
      raise GenerationError, "Two definitions are named #{definition.name}" if @definitions.key?(definition.name)

      @definitions[definition.name] = definition
      definition.name
    end

    def literal(value, where)
      case value
      when String then JSON.generate(value)
      when Integer, true, false then value.to_s
      else raise GenerationError, "#{where}: enum values must be strings, integers or booleans"
      end
    end

    def union(members)
      unique = members.uniq
      nullable = unique.delete("nil")
      expression = unique.join(" | ")
      return expression unless nullable
      return "nil" if unique.empty?

      unique.size == 1 && !expression.include?(" | ") ? "#{expression}?" : "(#{expression})?"
    end

    def nullable(expression)
      expression.include?(" | ") ? "(#{expression})?" : "#{expression}?"
    end

    # Translation of schemas into type expressions.

    def check_keywords(value, where)
      unknown = (value.keys - ANNOTATION_KEYWORDS - STRUCTURE_KEYWORDS).sort
      raise GenerationError, "#{where}: unsupported keywords #{unknown.join(", ")}" unless unknown.empty?
    end

    def reference(value, where)
      target = text(value["$ref"], where)
      prefix = "#/components/schemas/"
      name = target.delete_prefix(prefix)
      unless target.start_with?(prefix) && @schemas.key?(name)
        raise GenerationError,
              "#{where}: unknown reference #{target}"
      end
      raise GenerationError, "#{where}: $ref with sibling keywords" if (value.keys - ANNOTATION_KEYWORDS).size > 1

      name
    end

    def types_of(value, where)
      declared = value["type"]
      return [] if declared.nil?
      return [declared] if declared.is_a?(String)

      list(declared, where).map { |item| text(item, where) }
    end

    # A type expression for `value`; inline enums and objects become definitions named `hint`.
    def render(value, hint, where, top: false)
      check_keywords(value, where)
      return alias_name(reference(value, where)) if value.key?("$ref")

      %w[allOf anyOf oneOf].each do |combinator|
        return render_combination(value, combinator, hint, where) if value.key?(combinator)
      end
      types = types_of(value, where)
      null = types.include?("null")
      types -= ["null"]
      raise GenerationError, "#{where}: `not` is only supported on objects" if value.key?("not") && types != ["object"]

      if value.key?("const")
        expression = literal(value["const"], where)
        return null ? nullable(expression) : expression
      end
      return render_enum(value, hint, where, null:, top:) if value.key?("enum")
      raise GenerationError, "#{where}: several non-null types" if types.size > 1
      return "nil" if null && types.empty?

      expression = render_kind(value, types.first, hint, where)
      null ? nullable(expression) : expression
    end

    def render_kind(value, kind, hint, where)
      case kind
      when "string", "integer", "number", "boolean" then SCALARS.fetch(kind)
      when "array"
        items = schema(value.fetch("items", {}), "#{where}.items")
        "Array[#{render(items, "#{hint}Item", "#{where}.items")}]"
      when "object" then render_object(value, hint, where)
      when nil
        return render_object(value, hint, where) if value.key?("properties")
        return "untyped" if (value.keys - ANNOTATION_KEYWORDS).empty?

        raise GenerationError, "#{where}: unsupported schema"
      else raise GenerationError, "#{where}: unsupported type #{kind.inspect}"
      end
    end

    def render_enum(value, hint, where, null:, top:)
      values = list(value["enum"], "#{where}.enum")
      null ||= values.include?(nil)
      members = values.compact.map { |item| literal(item, where) }
      raise GenerationError, "#{where}: an enum with no values" if members.empty?

      expression = members.join(" | ")
      if top
        return null ? "(#{expression})?" : expression
      end

      name = define(Definition.new(alias_name(hint), describe(value), nil, expression))
      null ? "#{name}?" : name
    end

    def render_combination(value, combinator, hint, where)
      structure = (value.keys & STRUCTURE_KEYWORDS) - [combinator, "discriminator"]
      raise GenerationError, "#{where}: #{combinator} with #{structure.sort.join(", ")}" unless structure.empty?

      members = list(value[combinator], where).map { |member| schema(member, where) }
      if combinator == "allOf" && members.size != 1
        raise GenerationError,
              "#{where}: allOf is only supported with one member"
      end

      expressions = members.each_with_index.map do |member, index|
        render(member, hint, "#{where}.#{combinator}[#{index}]")
      end
      check_discriminator(value, members, where) if value.key?("discriminator")
      union(expressions)
    end

    # A discriminated union narrows on its property: every mapping must match the members.
    def check_discriminator(value, members, where)
      discriminator = schema(value["discriminator"], "#{where}.discriminator")
      name = text(discriminator["propertyName"], "#{where}.discriminator.propertyName")
      mapping = schema(discriminator.fetch("mapping", {}), "#{where}.discriminator.mapping")
      referenced = members.select { |member| member.key?("$ref") }.map { |member| reference(member, where) }
      if referenced.size != members.size
        raise GenerationError,
              "#{where}: a discriminated union must list references only"
      end

      mapping.each do |discriminant, target|
        target_name = text(target, where).delete_prefix("#/components/schemas/")
        unless referenced.include?(target_name)
          raise GenerationError,
                "#{where}: mapping #{discriminant} points outside the union"
        end

        properties = schema(schema(@schemas[target_name], target_name).fetch("properties", {}), target_name)
        property = schema(properties.fetch(name, {}), "#{target_name}.#{name}")
        allowed = property.key?("enum") ? property["enum"] : [property["const"]]
        unless list(allowed, "#{target_name}.#{name}").include?(discriminant)
          raise GenerationError, "#{where}: #{target_name}.#{name} does not allow #{discriminant}"
        end
      end
    end

    def render_object(value, hint, where)
      return define_record(hint, value, where) if value.key?("properties")

      extra = value["additionalProperties"]
      return "Hash[Symbol, #{render(extra, "#{hint}Value", "#{where}.additionalProperties")}]" if extra.is_a?(Hash)

      "Hash[Symbol, untyped]"
    end

    # Definitions.

    def define_record(hint, value, where)
      unexpected = value.keys & %w[allOf anyOf oneOf enum const items]
      if !unexpected.empty? || ![[], ["object"]].include?(types_of(value, where))
        raise GenerationError, "#{where}: properties mixed with other types"
      end

      check_not(value, where) if value.key?("not")
      extra = value["additionalProperties"]
      raise GenerationError, "#{where}: typed members with typed additionalProperties" unless [nil, true,
                                                                                               false].include?(extra)

      properties = schema(value.fetch("properties", {}), "#{where}.properties")
      required = list(value.fetch("required", []), where).map { |item| text(item, where) }
      missing = required - properties.keys
      raise GenerationError, "#{where}: required members without a schema: #{missing.sort}" unless missing.empty?

      # Extra members (`additionalProperties: true`) cannot be typed: the description says so.
      definition = Definition.new(alias_name(hint), describe(value), [], nil)
      define(definition)
      properties.each do |key, member|
        raise GenerationError, "#{where}: the member #{key.inspect} is not a valid record key" unless KEY.match?(key)

        member_schema = schema(member, "#{where}.#{key}")
        type = render(member_schema, "#{hint}#{OpenAPI.upper_first(key)}", "#{where}.#{key}")
        definition.fields << Field.new(key, type, required.include?(key), describe(member_schema))
      end
      definition.name
    end

    # `not: {required: [...]}` forbids members: a record leaves them undeclared.
    def check_not(value, where)
      forbidden = schema(value["not"], "#{where}.not")
      raise GenerationError, "#{where}: `not` is only supported as not.required" unless forbidden.keys == ["required"]

      properties = schema(value.fetch("properties", {}), where)
      list(forbidden["required"], "#{where}.not.required").each do |key|
        raise GenerationError, "#{where}: #{key} is both declared and forbidden" if properties.key?(text(key, where))
      end
    end

    def define_component(name, value)
      where = "components.schemas.#{name}"
      check_keywords(value, where)
      return define_record(name, value, where) if value.key?("properties")

      define(Definition.new(alias_name(name), describe(value), nil, render(value, name, where, top: true)))
    end

    # A record for the query of every operation that takes one, named after it, with the parameters
    # of its path item and its own (the operation's win, by name and location).
    def define_queries
      schema(@document.fetch("paths", {}), "paths").each do |path, raw_item|
        item = schema(raw_item, path)
        unknown = (item.keys - METHODS - PATH_ITEM_KEYS).sort
        raise GenerationError, "#{path}: unsupported path item keys #{unknown.join(", ")}" unless unknown.empty?

        shared = list(item.fetch("parameters", []), "#{path}.parameters")
        (item.keys & METHODS).each do |method|
          operation = schema(item[method], "#{method} #{path}")
          operation_id = text(operation["operationId"], "#{method} #{path}")
          define_query(operation_id, method, path, shared + list(operation.fetch("parameters", []), operation_id))
        end
      end
    end

    def define_query(operation_id, method, path, raw_parameters)
      hint = "#{OpenAPI.upper_first(operation_id)}Query"
      definition = Definition.new(alias_name(hint), "", [], nil)
      parameters = raw_parameters.map { |raw| parameter(schema(raw, operation_id), operation_id) }
      parameters = parameters.reverse.uniq { |parameter| [parameter["name"], parameter["in"]] }.reverse
      parameters.each do |parameter|
        check_parameter(parameter, operation_id)
        next unless parameter["in"] == "query"

        key = text(parameter["name"], operation_id)
        where = "#{operation_id}.#{key}"
        raise GenerationError, "#{where}: not a valid record key" unless KEY.match?(key)

        value = schema(parameter["schema"], where)
        type = render(value, "#{hint}#{OpenAPI.upper_first(key)}", where)
        doc = [describe(parameter), describe(value)].reject(&:empty?).join(" ")
        definition.fields << Field.new(key, type, parameter["required"] == true, doc)
      end
      return if definition.fields.empty?

      definition.doc = "The query of `#{operation_id}` (#{method.upcase} #{path})."
      define(definition)
    end

    # A parameter this generator can type: a schema, no serialization settings.
    def check_parameter(parameter, operation_id)
      where = "#{operation_id}.#{parameter["name"]}"
      unknown = (parameter.keys - PARAMETER_KEYS).sort
      raise GenerationError, "#{where}: unsupported parameter keys #{unknown.join(", ")}" unless unknown.empty?
      raise GenerationError, "#{where}: a parameter without a schema" unless parameter["schema"].is_a?(Hash)
    end

    def parameter(value, where)
      return value unless value.key?("$ref")

      target = text(value["$ref"], where)
      name = target.delete_prefix("#/components/parameters/")
      unless target.start_with?("#/components/parameters/") && @parameters.key?(name)
        raise GenerationError, "#{where}: unknown parameter #{target}"
      end

      schema(@parameters[name], target)
    end

    # The comment of a schema: its description, then its format and default.
    def describe(value)
      parts = []
      description = value["description"]
      parts << description.split.join(" ") if description.is_a?(String) && !description.strip.empty?
      format = value["format"]
      parts << "Format: #{format}." if format.is_a?(String) && !%w[binary password].include?(format)
      parts << "Default: `#{JSON.generate(value["default"])}`." if value.key?("default")
      parts.join(" ")
    end

    # Output.

    def comment(doc, indent)
      return [] if doc.empty?

      width = LINE_LENGTH - indent.length - 2
      lines = [+""]
      doc.split.each do |word|
        if lines.last.empty?
          lines.last << word
        elsif lines.last.length + 1 + word.length <= width
          lines.last << " " << word
        else
          lines << word.dup
        end
      end
      lines.map { |line| "#{indent}# #{line}" }
    end

    def emit(definition)
      indent = INDENT * 2
      lines = comment(definition.doc, indent)
      if definition.fields.nil?
        lines.concat(emit_alias("#{indent}type #{definition.name} = ", definition.expression, indent))
        return lines.join("\n")
      end

      return (lines << "#{indent}type #{definition.name} = {}").join("\n") if definition.fields.empty?

      lines << "#{indent}type #{definition.name} = {"
      definition.fields.each_with_index do |field, index|
        lines << "" if index.positive? && !field.doc.empty?
        lines.concat(comment(field.doc, "#{indent}#{INDENT}"))
        separator = index == definition.fields.size - 1 ? "" : ","
        line = "#{indent}#{INDENT}#{"?" unless field.required}#{field.name}: #{field.type}#{separator}"
        if line.length > LINE_LENGTH
          raise GenerationError,
                "#{definition.name}.#{field.name}: the type is too long for one line"
        end

        lines << line
      end
      lines << "#{indent}}"
      lines.join("\n")
    end

    # `type name = expression`, one member per line when it is too long.
    def emit_alias(prefix, expression, indent)
      line = "#{prefix}#{expression}"
      return [line] if line.length <= LINE_LENGTH

      members = split_union(expression)
      raise GenerationError, "#{prefix.strip} is too long and cannot be split" if members.size < 2

      ["#{prefix}#{members.first}", *members.drop(1).map { |member| "#{indent}#{INDENT}| #{member}" }]
    end

    # The index of the quote that closes the string literal opened at `start`.
    def string_end(expression, start)
      finish = start + 1
      finish += expression[finish] == "\\" ? 2 : 1 until expression[finish] == '"'
      finish
    end

    # Splits a union on its top-level ` | `, outside parentheses, brackets and strings.
    def split_union(expression)
      parts = []
      depth = 0
      current = +""
      index = 0
      while index < expression.length
        char = expression[index]
        if char == '"'
          finish = string_end(expression, index)
          current << expression[index..finish]
          index = finish + 1
          next
        end
        depth += 1 if "([{".include?(char)
        depth -= 1 if ")]}".include?(char)
        if depth.zero? && expression[index, 3] == " | "
          parts << current
          current = +""
          index += 3
          next
        end
        current << char
        index += 1
      end
      parts << current
    end
  end

  def generate(contract)
    Generator.new(JSON.parse(contract)).generate
  end

  # Where the contract came from, and its text.
  def download
    source_file = ENV.fetch("FLASHPI_OPENAPI_FILE", "")
    return [source_file, File.read(source_file, encoding: "UTF-8")] unless source_file.empty?

    url = ENV.fetch("FLASHPI_OPENAPI_URL", DEFAULT_URL)
    [url, fetch(URI.parse(url), 5)]
  end

  # Downloads over HTTPS only, following up to `redirects` redirects to HTTPS URLs; any other is
  # refused before it is requested.
  def fetch(uri, redirects)
    raise "Refusing to download the contract over a non-HTTPS URL: #{uri}" unless uri.is_a?(URI::HTTPS)

    response = Net::HTTP.start(uri.host, uri.port, use_ssl: true, open_timeout: 30, read_timeout: 60) do |http|
      http.request(Net::HTTP::Get.new(uri, "accept" => "application/json"))
    end
    case response
    when Net::HTTPSuccess then response.body.to_s.dup.force_encoding(Encoding::UTF_8)
    when Net::HTTPRedirection
      raise "Too many redirects while downloading the contract" if redirects.zero?

      fetch(uri + response["location"].to_s, redirects - 1)
    else raise "Downloading the contract failed: #{response.code}"
    end
  end

  def main(argv)
    mode = argv.first || "generate"
    unless %w[sync generate check].include?(mode) && argv.size <= 1
      warn "Usage: ruby scripts/openapi.rb sync|generate|check"
      return 2
    end
    if mode == "sync"
      source, contract = download
      parsed = JSON.parse(contract) # fail early on a broken document
      unless parsed.is_a?(Hash) && parsed.key?("openapi") && parsed.key?("paths")
        raise "The downloaded file is not an OpenAPI document"
      end

      File.write(CONTRACT_PATH, contract.end_with?("\n") ? contract : "#{contract}\n")
      puts "Copied #{source} to openapi/openapi.json"
    end
    types = generate(File.read(CONTRACT_PATH, encoding: "UTF-8"))
    relative = TYPES_PATH.delete_prefix("#{ROOT}/")
    if mode == "check"
      current = File.exist?(TYPES_PATH) ? File.read(TYPES_PATH, encoding: "UTF-8") : ""
      if current != types
        warn "#{relative} is out of date. Run: ruby scripts/openapi.rb generate"
        return 1
      end
      puts "#{relative} matches openapi/openapi.json"
      return 0
    end
    File.write(TYPES_PATH, types)
    puts "Wrote #{relative}"
    0
  end
end

exit(OpenAPI.main(ARGV)) if $PROGRAM_NAME == __FILE__
